func stagedPaths(r *repo) ([]string, error) {
	out, err := r.git("diff", "--cached", "--name-only", "--no-renames", "--relative")
	if err != nil {
		return nil, err
	}
	var paths []string
	start := 0
	for i := 0; i <= len(out); i++ {
		if i == len(out) || out[i] == '\n' {
			if line := out[start:i]; line != "" {
				paths = append(paths, line)
			}
			start = i + 1
		}
	}
	return mergeFiltered(r, paths), nil
}

